const fs = require("fs");
const path = require("path");

const TEMPLATES_ROOT = path.join(
    process.cwd(),
    "src",
    "templates",
    "metadata",
    "view"
);
const OVERRIDES_ROOT = path.join(TEMPLATES_ROOT, "overrides");
const OUTPUT = path.join(TEMPLATES_ROOT, "registry.generated.ts");

const BANNER = `/**
 * AUTO-GENERATED by \`npm run generate:template-registry\`, which also runs from
 * next.config.js on \`next dev\` and \`next build\`. DO NOT HAND-EDIT.
 *
 * Every overrides/{SCHEMA_NAME}/{version}/index.mdx is registered here, along
 * with its optional sibling components.tsx. To add a template, create the
 * folder - nothing else needs editing.
 */`;

function discover() {
    if (!fs.existsSync(OVERRIDES_ROOT)) return [];

    return fs
        .readdirSync(OVERRIDES_ROOT, { withFileTypes: true })
        .filter(entry => entry.isDirectory())
        .flatMap(schemaDir =>
            fs
                .readdirSync(path.join(OVERRIDES_ROOT, schemaDir.name), {
                    withFileTypes: true,
                })
                .filter(versionDir => versionDir.isDirectory())
                .filter(versionDir =>
                    fs.existsSync(
                        path.join(
                            OVERRIDES_ROOT,
                            schemaDir.name,
                            versionDir.name,
                            "index.mdx"
                        )
                    )
                )
                .map(versionDir => ({
                    schemaName: schemaDir.name,
                    schemaVersion: versionDir.name,
                    hasComponents: fs.existsSync(
                        path.join(
                            OVERRIDES_ROOT,
                            schemaDir.name,
                            versionDir.name,
                            "components.tsx"
                        )
                    ),
                    source: `overrides/${schemaDir.name}/${versionDir.name}/index.mdx`,
                }))
        )
        .sort((a, b) =>
            `${a.schemaName}/${a.schemaVersion}`.localeCompare(
                `${b.schemaName}/${b.schemaVersion}`
            )
        );
}

function render(templates) {
    const imports = templates
        .flatMap(({ schemaName, schemaVersion, hasComponents }, i) => {
            const base = `./overrides/${schemaName}/${schemaVersion}`;
            const lines = [
                `import T${i}, { meta as m${i} } from "${base}/index.mdx";`,
            ];
            if (hasComponents) {
                lines.push(
                    `import { makeComponents as c${i} } from "${base}/components";`
                );
            }
            return lines;
        })
        .join("\n");

    const entries = templates
        .map(
            ({ schemaName, schemaVersion, hasComponents, source }, i) =>
                `    {
        schemaName: ${JSON.stringify(schemaName)},
        schemaVersion: ${JSON.stringify(schemaVersion)},
        source: ${JSON.stringify(source)},
        Template: T${i},
        meta: m${i},
        makeComponents: ${hasComponents ? `c${i}` : "undefined"},
    },`
        )
        .join("\n");

    return `${BANNER}

import { GeneratedTemplate } from "./meta";
${imports}

export const generatedTemplates: GeneratedTemplate[] = [
${entries}
];
`;
}

function generateTemplateRegistry() {
    const templates = discover();
    const next = render(templates);
    const current = fs.existsSync(OUTPUT)
        ? fs.readFileSync(OUTPUT, "utf-8")
        : null;

    if (current !== next) {
        fs.writeFileSync(OUTPUT, next);
    }

    return templates;
}

module.exports = generateTemplateRegistry;

if (require.main === module) {
    const templates = generateTemplateRegistry();
    console.log(
        `Wrote src/templates/metadata/view/registry.generated.ts (${templates.length} templates)`
    );
    templates.forEach(t =>
        console.log(`  ${t.schemaName} ${t.schemaVersion} -> ${t.source}`)
    );
}
